"""B5: Validate and summarize the retention list generated by lapse_prediction.

The retention list is created as part of the lapse-prediction pipeline because
it depends on the selected model's test-set predictions and the exported
customer segment labels. This module validates that saved deliverable without
retraining the model or generating duplicate records.
"""

from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parents[2]
RETENTION_FILE = ROOT / "outputs" / "retention_list.csv"

REQUIRED_COLUMNS = {
    "customer_id",
    "lapse_probability",
    "actually_lapsed"
}


def main() -> None:
    if not RETENTION_FILE.exists():
        raise FileNotFoundError(
            "Retention list not found. Run "
            "`python -m src.part_b.lapse_prediction` first."
        )

    retention = pd.read_csv(RETENTION_FILE)

    missing = REQUIRED_COLUMNS.difference(retention.columns)
    if missing:
        raise ValueError(
            f"Retention list is missing columns: {sorted(missing)}"
        )

    if len(retention) > 10:
        raise ValueError(
            f"Expected at most 10 retention candidates, found {len(retention)}"
        )

    if retention["customer_id"].duplicated().any():
        raise ValueError("Duplicate customer IDs found in retention list.")

    if not retention["lapse_probability"].between(0, 1).all():
        raise ValueError("Lapse probabilities must be between 0 and 1.")

    actually_lapsed = int(retention["actually_lapsed"].sum())

    print("RETENTION LIST VALIDATION PASSED")
    print(f"Candidates: {len(retention)}")
    print(f"Actually lapsed in list: {actually_lapsed}")
    print(f"Validated file: {RETENTION_FILE.relative_to(ROOT)}")


if __name__ == "__main__":
    main()